// createThroughCore is CreateOne on the repository's transaction: input's row
// stamped, created by the behaviors' core, whose uses initialize the fields
// they own, with the columns the insert writes, and read back.
func (r *RefundRepository) createThroughCore(ctx context.Context, input *RefundCreate) (*types.Refund, error) {
	row := input.row()
	columns, err := r.createColumns(row)
	if err != nil {
		return nil, err
	}
	opts := &rules.CreateOptions{ID: r.createKey(row), ExecuteOptions: rules.ExecuteOptions{OwnColumns: columns}}
	key, err := rules.RunCreate(ctx, rulesHost(r.tx), "Refund", r.coreOwn(row), behaviorCaller(ctx), opts)
	if err != nil {
		return nil, err
	}
	id, err := types.ParseIdentityUUID(key)
	if err != nil {
		return nil, fmt.Errorf("create Refund: the core's key %q: %w", key, err)
	}
	return r.GetOne(ctx, id, nil)
}

// upsertInputs are inputs as an upsert inserts them (D103): each one's row
// with the fields its behaviors own as the core's create of it gives them,
// run to its change set and not applied, so the insert writes what CreateOne
// would have, and the update, which sets none of them, leaves them as the
// row holds them. A refusal of the core's is returned before anything is
// written.
func (r *RefundRepository) upsertInputs(ctx context.Context, inputs []*RefundCreate) ([]*types.Refund, error) {
	host := rulesHost(r.tx)
	rows := make([]*types.Refund, 0, len(inputs))
	for _, input := range inputs {
		row := input.row()
		owned, err := rules.PrepareCreate(ctx, host, "Refund", r.coreOwn(row), behaviorCaller(ctx), &rules.CreateOptions{ID: r.createKey(row)})
		if err != nil {
			return nil, err
		}
		if value, ok := owned["Payments"]["due"]; ok {
			if err := json.Unmarshal(value, &row.PaymentsDue); err != nil {
				return nil, fmt.Errorf("upsert Refund: the core's Payments.due %s: %w", value, err)
			}
		}
		if value, ok := owned["Payments"]["authorized"]; ok {
			if err := json.Unmarshal(value, &row.PaymentsAuthorized); err != nil {
				return nil, fmt.Errorf("upsert Refund: the core's Payments.authorized %s: %w", value, err)
			}
		}
		if value, ok := owned["Payments"]["captured"]; ok {
			if err := json.Unmarshal(value, &row.PaymentsCaptured); err != nil {
				return nil, fmt.Errorf("upsert Refund: the core's Payments.captured %s: %w", value, err)
			}
		}
		if value, ok := owned["Payments"]["refunded"]; ok {
			if err := json.Unmarshal(value, &row.PaymentsRefunded); err != nil {
				return nil, fmt.Errorf("upsert Refund: the core's Payments.refunded %s: %w", value, err)
			}
		}
		if value, ok := owned["Payments"]["outstanding"]; ok {
			if err := json.Unmarshal(value, &row.PaymentsOutstanding); err != nil {
				return nil, fmt.Errorf("upsert Refund: the core's Payments.outstanding %s: %w", value, err)
			}
		}
		if value, ok := owned["Payments"]["overpaid"]; ok {
			if err := json.Unmarshal(value, &row.PaymentsOverpaid); err != nil {
				return nil, fmt.Errorf("upsert Refund: the core's Payments.overpaid %s: %w", value, err)
			}
		}
		if value, ok := owned["Payments"]["currency"]; ok {
			if err := json.Unmarshal(value, &row.PaymentsCurrency); err != nil {
				return nil, fmt.Errorf("upsert Refund: the core's Payments.currency %s: %w", value, err)
			}
		}
		if value, ok := owned["Payments"]["state"]; ok {
			if err := json.Unmarshal(value, &row.PaymentsState); err != nil {
				return nil, fmt.Errorf("upsert Refund: the core's Payments.state %s: %w", value, err)
			}
		}
		if value, ok := owned["status"]["status"]; ok {
			if err := json.Unmarshal(value, &row.Status); err != nil {
				return nil, fmt.Errorf("upsert Refund: the core's status.status %s: %w", value, err)
			}
		}
		if at, err := rules.TimeOfMillis(owned["status"]["enteredAt"]); err != nil {
			return nil, fmt.Errorf("upsert Refund: the core's status.enteredAt: %w", err)
		} else if at != nil {
			value := types.TemporalDateTime(*at)
			row.StatusEnteredAt = &value
		}
		rows = append(rows, row)
	}
	return rows, nil
}

